            [{"k": "date", "l": T("First day", "Birinchi kün", "Первый день"), "w": 1}, {"k": "date", "l": T("Last day", "Akırkı kün", "Последний день"), "w": 1}, {"k": "boxes", "l": T("Opening of doors (hh:mm)", "Eshik achıluu (ss:mm)", "Открытие дверей (чч:мм)"), "n": 5, "w": .9}, {"k": "boxes", "l": T("End (hh:mm)", "Bütüshü (ss:mm)", "Окончание (чч:мм)"), "n": 5, "w": .8}],
            [{"k": "date", "l": T("Setting up from", "Ornotuu (kündön)", "Монтаж с"), "w": 1}, {"k": "date", "l": T("Dismantling completed by", "Chechüü (künge cheyin)", "Демонтаж до"), "w": 1}, {"k": "boxes", "l": T("Date-of-mourning confirmation No.", "Aza künü emes ekenin tastıktoo nomeri", "№ подтверждения (не день траура)"), "n": 8, "w": 1.7}],
