            [{"k": "line", "l": T("Address or description of the site (for a square or park: the part used, with a sketch attached)", "Darek je jerdin süröttölüshü", "Адрес или описание участка (для площади или парка — используемая часть, со схемой)"), "w": 2.2}, {"k": "check", "l": T("Venue", "Jay", "Площадка"), "opts": [T("indoor", "jabık", "закрытая"), T("open air", "achık", "открытая")], "cols": 2, "w": 1}],
            [{"k": "line", "l": T("Owner of the venue and date of the written consent", "Jaydın eesi jana makulduk kattın künü", "Владелец площадки и дата письменного согласия"), "w": 2}, {"k": "boxes", "l": T("Certified capacity (persons)", "Tastıktalgan sıyımdıgı (adam)", "Паспортная вместимость (чел.)"), "n": 6, "w": 1.2}],
            {"k": "check", "l": T("Road closure or restriction of traffic required (considered by the transport committee on Wednesdays)", "Joldu jabuu je kıymıldı chekteö kerek (transport komiteti sharshembi künü karayt)", "Требуется перекрытие или ограничение движения (рассматривает транспортная комиссия по средам)"), "opts": [T("no", "jok", "нет"), T("yes: streets and hours stated on a separate sheet", "ooba: köchölör jana saattar özüncho barakta", "да: улицы и часы на отдельном листе")], "cols": 2},
