        {"k": "check", "l": "decision", "opts": ["granted", "refused", T("placed on the waiting list", "kütüü tizmesine koyuldu", "внесён в лист ожидания")], "cols": 3},
        [{"k": "money", "l": T("Place fee per day / month / season", "Orundun akısı (kün / ay / mezgil)", "Плата за место (день / месяц / сезон)"), "n": 8, "w": 1.3}, {"k": "boxes", "l": T("Trader's card No. issued", "Berilgen soodagerdin kartochkası", "№ выданной карточки торговца"), "n": 8, "w": 1.1}],
        {"k": "sign", "l": [T("Director of the market administration", "Bazar administratsiyasının direktoru", "Директор администрации рынка"), "date"]},
