            {"k": "check", "l": T("The sign is placed", "Tablichka ornotulat", "Вывеска размещается"), "opts": [T("flat on the facade", "fasadka jalpak", "плоско на фасаде"), T("projecting (bracket)", "chıgıp turgan (kronshteyn)", "консольная (кронштейн)"), T("on the roof or parapet", "chatırda je parapette", "на крыше или парапете"),
                T("in the window (inside)", "terezede (ichinde)", "в витрине (внутри)"), T("free-standing (stand, pylon)", "özüncho turgan (stend, pilon)", "отдельно стоящая (стенд, пилон)"), T("on a fence or awning", "tosmodo je kalkada", "на ограждении или навесе")], "cols": 3},
            [{"k": "check", "l": T("Building in a protected zone (Heritage Department approval attached)", "Imarat korgoluuchu zonada", "Здание в охранной зоне (прилагается согласование Департамента наследия)"), "opts": YESNO, "cols": 2, "w": 1.5}, {"k": "boxes", "l": T("Height of the lower edge above the pavement, cm", "Tömönkü cheginin biyiktigi, sm", "Высота нижнего края над тротуаром, см"), "n": 4, "w": 1.3}],
