            {"k": "check", "l": T("Illumination", "Jarıktandıruu", "Подсветка"), "opts": [T("none", "jok", "нет"), T("lit from outside (spotlights)", "tıshtan (prozhektor)", "внешняя (прожекторы)"), T("lit from inside (light box)", "ichten (jarık kutu)", "внутренняя (световой короб)"),
                T("individual lit letters", "jarık tamgalar", "объёмные световые буквы"), T("neon or LED tube", "neon je LED tütükchö", "неон или светодиодная трубка"), T("screen or moving image (not permitted)", "ekran je kıymıldagan süröt (uruksat berilbeyt)", "экран или движущееся изображение (не допускается)")], "cols": 3},
            [{"k": "boxes", "l": T("Power, W", "Kuvatı, Vt", "Мощность, Вт"), "n": 5, "w": 1}, {"k": "line", "l": T("Lit from ... to ... (hours); Electric Networks technical conditions No.", "Jarık saattarı; elektr tarmaktarının shartarı No.", "Часы работы подсветки; № технических условий электросетей"), "w": 2.4}],
            {"k": "line", "l": T("Materials (frame, face, letters) and colours (by RAL number)", "Materialdar jana tüstör (RAL nomeri boyuncha)", "Материалы (каркас, лицевая часть, буквы) и цвета (по RAL)")},
