            [{"k": "line", "l": T("Depot or night parking of the vehicle (address)", "Unaanın deposu je tünkü turaktoosu (dareki)", "Депо или ночная стоянка (адрес)"), "w": 2}, {"k": "line", "l": T("Agreement with (owner), No., date", "Kelishim (ee), nomeri, künü", "Договор с (владелец), №, дата"), "w": 1.5}],
